(function(root){'use strict';
const clone=v=>JSON.parse(JSON.stringify(v)),now=()=>new Date().toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});
const members=['小林','小王','阿悦'],types={schedule:'排期',theme:'活动主题',plan:'活动方案',text:'文字资料',image:'图片素材',wechat:'公众号推文',xhs:'小红书推文'};
const uid=p=>p+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7),get=(s,id)=>s.nodes.find(n=>n.id===id),type=n=>n.kind==='post'?n.platform:n.kind;
const facts=()=>({title:'12月职业探索活动',date:'2026年12月12日 14:00—16:30',place:'青年活动中心 · 创作空间',audience:'对产品设计感兴趣的青年',count:'30',signup:'https://example.org/signup',requirement:'职业介绍与动手体验，制作公众号和小红书招募推文。',source:'团队12月活动排期 · 演示资料'});
function log(s,text){s.events.unshift({text,actor:s.actor,at:now()});}
function snap(n){const a=clone(n);delete a.history;delete a.finalized;return a;}
function checkpoint(s,n,label){n.history ||= [];n.history.unshift({label,actor:s.actor,at:now(),snapshot:snap(n)});}
function storeAsset(s,data){s.assets ||= {};const old=Object.keys(s.assets).find(id=>s.assets[id]===data);if(old)return old;const id=uid('asset');s.assets[id]=data;return id;}
function collectAssets(s){const used=new Set();function walk(o){if(!o||typeof o!=='object')return;for(const [k,v] of Object.entries(o))if(k==='photo'&&typeof v==='string')used.add(v);else walk(v);}walk(s.nodes);walk(s.undo);for(const id of Object.keys(s.assets||{}))if(!used.has(id))delete s.assets[id];}
function migrateAssets(s){s.assets ||= {};function walk(o){if(!o||typeof o!=='object')return;for(const k of Object.keys(o)){if(k==='assets')continue;if(k==='photo'&&typeof o[k]==='string'&&o[k].startsWith('data:image/'))o[k]=storeAsset(s,o[k]);else walk(o[k]);}}walk(s);}
function remember(s,label){s.undo ||= [];s.undo.push({label,nodes:clone(s.nodes),groups:clone(s.groups),comments:clone(s.comments),selected:s.selected,selection:clone(s.selection),schedule:clone(s.schedule)});if(s.undo.length>10)s.undo.shift();}
function undo(s){const u=s.undo.pop();if(!u)throw Error('没有可撤销的操作');Object.assign(s,{nodes:u.nodes,groups:u.groups,comments:u.comments,selected:u.selected,selection:u.selection,schedule:u.schedule});log(s,'撤销：'+u.label);return u.label;}
function sourceRef(n){return {id:n.id,name:n.name,kind:n.kind,version:n.revision,snapshot:snap(n)};}
function planDraft(s,t){return {goal:`围绕“${t?.title||s.project}”，${t?.direction||'从身边的问题开始，练习观察、构思与表达。'}`,audience:s.schedule.audience,agenda:'14:00—14:15 签到与破冰\n14:15—14:45 职业介绍与案例\n14:45—15:50 创意与草图体验\n15:50—16:30 小组交流',focus:'强调职业探索与动手实践，清楚说明时间、地点和报名方式。'};}
function planInput(s,id='plan'){const p=get(s,id);return p?.kind==='plan'?{sourceId:p.id,version:p.revision,content:clone(p.content),topic:p.topic||s.project,facts:clone(s.schedule)}:{sourceId:null,version:0,content:planDraft(s),topic:s.project,facts:clone(s.schedule)};}
function imageFor(s,input,platform,round=1){return {title:platform==='xhs'?'把好奇变成一个设计':'来体验产品设计师的一天',subtitle:input.content.focus,date:(input.facts||s.schedule).date,place:(input.facts||s.schedule).place,background:round%2?'#F4F4F0':'#EBEBE6',ink:'#16181B',fontSize:42,layout:round%2?'left':'center',round,photo:'',source:'本地模板排版 · 模拟生成，非现场照片',usable:true};}
function textFor(s,input,platform,part){const f=input.facts||s.schedule;if(part==='title')return (input.topic||s.project)+(platform==='xhs'?'｜从一个问题开始':'｜活动招募');return `${platform==='xhs'?'从身边的问题出发，一起体验设计。':'从一个具体问题开始，走近产品设计师的日常。\n\n一、为什么参与'}\n\n${input.content.goal}\n\n${platform==='xhs'?'一起做什么：':'二、活动安排'}\n${input.content.agenda}\n\n${platform==='xhs'?'活动信息':'三、活动信息'}\n面向：${input.content.audience}\n时间：${f.date}\n地点：${f.place}\n计划招募${f.count}人（非实际到场人数）\n报名：${f.signup}\n\n${platform==='xhs'?'#职业探索 #产品设计':'传播重点：'+input.content.focus}\n费用及参与条件：待团队核对。`;}
function makeNode(s,t,pos={x:100,y:100}){if(!types[t])throw Error('不支持该节点类型');const n={id:uid(t),kind:['wechat','xhs'].includes(t)?'post':t,name:types[t],x:Math.max(0,Number(pos.x)||0),y:Math.max(0,Number(pos.y)||0),revision:1,history:[],refs:[],ignoredRefs:{},finalized:null};if(n.kind==='schedule'){n.data=clone(s.schedule);n.data.title ||= '12月职业探索活动';}if(t==='theme')Object.assign(n,{title:s.project,direction:'从身边的问题开始，练习观察、构思与表达。',confirmed:null});if(t==='plan')Object.assign(n,{content:planDraft(s),topic:s.project,adopted:null});if(t==='text')Object.assign(n,{title:'活动资料',body:'在这里补充活动事实、文案要求或参考信息。',source:'团队补充 · 待核对'});if(t==='image')Object.assign(n,{title:'项目图片',image:imageFor(s,planInput(s),'xhs'),body:'填写画面说明；不自动识别图片。'});if(n.kind==='post'){n.platform=t;n.input=planInput(s,null);n.title=textFor(s,n.input,t,'title');n.body=textFor(s,n.input,t,'body');n.image=imageFor(s,n.input,t);}return n;}
function reaches(s,from,to,seen=new Set()){if(from===to)return true;if(seen.has(from))return false;seen.add(from);return (get(s,from)?.refs||[]).some(r=>!r.missing&&reaches(s,r.id,to,seen));}
function setRefs(s,id,ids){const n=get(s,id);if(!n)throw Error('节点不存在');const sources=[...new Set(ids)].map(key=>{const v=get(s,key);if(!v)throw Error('该来源已不存在，请重新选择');if(reaches(s,key,id))throw Error('此引用会形成循环，请选择其他资料');return v;});checkpoint(s,n,'变更引用前');n.refs=sources.map(sourceRef);n.ignoredRefs={};if(n.kind==='post'){const plan=sources.find(v=>v.kind==='plan');if(plan)n.input=planInput(s,plan.id);const image=sources.find(v=>v.kind==='image');if(image)Object.assign(n.image,{photo:image.image.photo,source:image.image.source,usable:image.image.usable});}n.revision++;n.finalized=null;return n;}
function createNode(s,t,pos,sourceIds=[]){const n=makeNode(s,t,pos);if(s.schema===3&&s.nodes.length){for(let i=0;i<=s.nodes.length;i++){const hit=s.nodes.find(v=>n.x<v.x+(v.kind==='post'?420:370)+30&&n.x+420>v.x-30&&n.y<v.y+650&&n.y+650>v.y);if(!hit)break;n.x=hit.x+(hit.kind==='post'?420:370)+60;}}s.nodes.push(n);try{if(sourceIds.length)setRefs(s,n.id,sourceIds);}catch(e){s.nodes.pop();throw e;}if(n.kind==='post'&&sourceIds.length){n.title=textFor(s,n.input,n.platform,'title');n.body=textFor(s,n.input,n.platform,'body');}log(s,'新增'+n.name);return n;}
function seed(){const s={schema:3,revision:0,actor:'我',project:'职业探索日 · 产品设计师体验',schedule:facts(),assets:{},nodes:[],groups:[],undo:[],comments:[],events:[],selected:'schedule',selection:['schedule'],view:{x:30,y:24,zoom:.75}};const positions=[[40,40],[350,40],[730,40],[1170,40],[1640,40]];['schedule','theme','plan','wechat','xhs'].forEach((t,i)=>{const n=createNode(s,t,{x:positions[i][0],y:positions[i][1]});n.id=t;n.x=positions[i][0];n.y=positions[i][1];s.nodes[s.nodes.length-1]=n;});get(s,'theme').refs=[sourceRef(get(s,'schedule'))];get(s,'plan').refs=[sourceRef(get(s,'theme'))];for(const id of ['wechat','xhs']){const n=get(s,id);n.refs=[sourceRef(get(s,'plan'))];n.input=planInput(s);n.example=true;}s.events=[];return s;}
function prepareCanvas(s){if(s.schema===3)return s;if(s.schema!==2)throw Error('不支持的数据版本');s.groups ||= [];s.undo ||= [];s.selection=s.selected?[s.selected]:[];s.assets ||= {};s.actor ||= '我';for(const n of s.nodes){n.name ||= types[type(n)]||n.title||'内容';n.history ||= [];n.refs ||= [];n.ignoredRefs ||= {};if(n.kind==='schedule'){n.data=clone(s.schedule);n.data.title ||= '12月职业探索活动';}if(n.kind==='plan'&&!n.content)n.content=planDraft(s,get(s,'theme'));}
for(const n of s.nodes){if(n.refs.length)continue;const source=n.kind==='post'?get(s,n.input?.sourceId||'plan'):n.kind==='plan'?get(s,'theme'):n.kind==='theme'?get(s,'schedule'):null;if(source){const r=sourceRef(source);if(n.kind==='post'&&n.input){r.version=n.input.version;r.snapshot.content=clone(n.input.content);r.snapshot.topic=n.input.topic;}n.refs=[r];if(n.kind==='post')n.input.sourceId=source.id;}}
s.schema=3;migrateAssets(s);return s;}
function update(s,id,field,value){const n=get(s,id);if(!n)throw Error('节点不存在');if(field.startsWith('content.'))n.content[field.slice(8)]=value;else if(field.startsWith('image.'))n.image[field.slice(6)]=value;else if(n.kind==='schedule'&&field!=='name')n.data[field]=value;else n[field]=value;if(n.id==='schedule')s.schedule=clone(n.data);n.revision++;n.finalized=null;if(n.kind==='theme')n.confirmed=null;if(n.kind==='post')n.example=false;return n;}
function withPhoto(s,id,data,source){const next=clone(s);update(next,id,'image.photo',storeAsset(next,data));update(next,id,'image.source',source);update(next,id,'image.usable',false);collectAssets(next);return next;}
function confirmTheme(s,id='theme'){const n=get(s,id);if(!n.title.trim())throw Error('请填写主题');n.confirmed={actor:s.actor,at:now(),version:n.revision};checkpoint(s,n,'确认主题');}
function adoptPlan(s,id='plan'){const n=get(s,id);if(Object.values(n.content).some(v=>!v.trim()))throw Error('请补全方案字段');n.adopted={actor:s.actor,at:now(),version:n.revision,content:clone(n.content)};checkpoint(s,n,'采用方案');}
function generatePlan(s,themeId='theme'){const t=get(s,themeId);const n=createNode(s,'plan',{x:t.x+400,y:t.y},[themeId]);n.content=planDraft(s,t);n.topic=t.title;return n;}
function generatePosts(s,platforms,planId='plan'){if(!platforms.length)throw Error('请至少选择一个平台');const p=get(s,planId);if(p?.kind!=='plan')throw Error('请选择活动方案');return platforms.map((t,i)=>createNode(s,t,{x:p.x+440+i*470,y:p.y+40+s.nodes.filter(n=>n.kind==='post'&&n.refs.some(r=>r.id===planId)).length*80},[planId]));}
function changedRefs(s,n){return (n.refs||[]).filter(r=>(r.missing||!get(s,r.id))&&n.ignoredRefs?.[r.id]!=='missing'||get(s,r.id)&&get(s,r.id).revision!==r.version&&n.ignoredRefs?.[r.id]!==get(s,r.id).revision);}
const stale=(s,n)=>changedRefs(s,n).length>0;
function keepRefs(s,id){const n=get(s,id);for(const r of n.refs)n.ignoredRefs[r.id]=get(s,r.id)?.revision||'missing';}
function syncRef(s,id,sourceId){const n=get(s,id),src=get(s,sourceId),r=n.refs.find(r=>r.id===sourceId);if(!src||!r)throw Error('来源已删除，请重新选择');checkpoint(s,n,'同步来源前（保留手改稿）');Object.assign(r,sourceRef(src));if(n.kind==='post'){if(src.kind==='plan'){n.input=planInput(s,src.id);n.title=textFor(s,n.input,n.platform,'title');n.body=textFor(s,n.input,n.platform,'body');}if(src.kind==='image')Object.assign(n.image,{photo:src.image.photo,source:src.image.source,usable:src.image.usable});}delete n.ignoredRefs[src.id];n.revision++;n.finalized=null;}
function refreshPost(s,id){for(const r of [...get(s,id).refs])if(get(s,r.id))syncRef(s,id,r.id);}
function regenerate(s,id,part){const n=get(s,id);if(n?.kind!=='post'||!['title','body','image'].includes(part))throw Error('请选择稿件与生成项');checkpoint(s,n,'重新生成'+part+'前');if(part==='image'){const old=n.image;n.image=imageFor(s,n.input,n.platform,(old.round||1)+1);Object.assign(n.image,{photo:old.photo,source:old.source,usable:old.usable});}else n[part]=textFor(s,n.input,n.platform,part);n.revision++;n.finalized=null;return n;}
function finalize(s,id){const n=get(s,id);if(!n?.title?.trim()||!n.body?.trim())throw Error('请补全标题和正文');if(!n.image.title.trim()||!n.image.source.trim()||!n.image.usable)throw Error('请核对配图来源与使用状态');if(stale(s,n))throw Error('来源已更新或删除，请先处理引用提示');n.finalized={actor:s.actor,at:now(),version:n.revision,snapshot:snap(n)};checkpoint(s,n,'确认定稿');}
function duplicate(s,id){const original=get(s,id),n=clone(original);n.id=uid(type(n));n.name+=' · 副本';n.x+=50;n.y+=80;n.revision=1;n.history=[];n.finalized=null;n.confirmed=null;n.adopted=null;s.nodes.push(n);return n;}
function impact(s,id){return s.nodes.filter(n=>n.refs.some(r=>r.id===id));}
function deleteNode(s,id){if(!get(s,id))throw Error('节点已不存在');s.nodes=s.nodes.filter(n=>n.id!==id);for(const n of s.nodes)for(const r of n.refs)if(r.id===id)r.missing=true;s.groups.forEach(g=>g.nodeIds=g.nodeIds.filter(key=>key!==id));s.groups=s.groups.filter(g=>g.nodeIds.length);s.selection=s.selection.filter(key=>key!==id);s.selected=s.selection[0]||s.nodes[0]?.id||'';log(s,'删除节点，已采用内容保留');}
function createGroup(s,ids,name){if(!name.trim())throw Error('请填写分组名称');const members=[...new Set(ids)].filter(id=>get(s,id));if(members.length<1)throw Error('请至少选择一个节点');for(const g of s.groups)g.nodeIds=g.nodeIds.filter(id=>!members.includes(id));s.groups=s.groups.filter(g=>g.nodeIds.length);const g={id:uid('group'),name:name.trim(),nodeIds:members,collapsed:false};s.groups.push(g);return g;}
function moveGroup(s,id,dx,dy){const g=s.groups.find(g=>g.id===id);if(!g)return;const nodes=g.nodeIds.map(id=>get(s,id)).filter(Boolean);dx=Math.max(dx,-Math.min(...nodes.map(n=>n.x)));dy=Math.max(dy,-Math.min(...nodes.map(n=>n.y)));nodes.forEach(n=>{n.x+=dx;n.y+=dy;});}
function ensureVisible(s,id){for(const g of s.groups)if(g.nodeIds.includes(id))g.collapsed=false;}
function materialFromPost(s,id){const post=get(s,id);const n=createNode(s,'image',{x:post.x+450,y:post.y});n.name=post.name+' · 配图素材';n.title=post.image.title;n.image=clone(post.image);n.poster=true;n.format=post.platform;return n;}
function comment(s,id,field,text){if(!text.trim())throw Error('请填写评论');const n=get(s,id);if(!n)throw Error('节点不存在');const c={id:uid('comment'),nodeId:id,field,text:text.trim(),actor:s.actor,at:now(),version:n.revision,mentions:members.filter(m=>text.includes('@'+m))};s.comments.push(c);return c;}
const api={clone,now,members,types,type,uid,get,seed,prepareCanvas,log,snap,checkpoint,storeAsset,collectAssets,migrateAssets,withPhoto,remember,undo,createNode,setRefs,changedRefs,stale,keepRefs,syncRef,update,planInput,confirmTheme,adoptPlan,generatePlan,generatePosts,regenerate,finalize,refreshPost,duplicate,impact,deleteNode,createGroup,moveGroup,ensureVisible,materialFromPost,comment};if(typeof module!=='undefined')module.exports=api;else root.CGY=api;
})(typeof window!=='undefined'?window:globalThis);
